    fontSize: 22
  });
  paramLabel.moveTo(pos);
  scene.add(paramLabel);
}

const controls = new Controls(scene, { position: 'top-right', width: 260 });
controls.addSlider({
  label: 'A (amplitude)',
  min: -3, max: 3, value: 1, step: 0.1,
  onChange: (v) => { A = v; updateCurve(); }
});
controls.addSlider({
  label: 'B (frequency)',
  min: 0.1, max: 4, value: 1, step: 0.1,
  onChange: (v) => { B = v; updateCurve(); }
});
